solution.code:
const ROOM = /^[a-z0-9-]{1,32}$/;
const BATAS = 50;

function buatServerChat({ jam }) {
  const rooms = new Map(); // room -> Set klien
  const pesan = []; // semua pesan, id naik
  const sudahAda = new Map(); // room|user|cid -> pesan
  let idTerakhir = 0;

  function balas(k, obj) {
    if (k.aktif) k.inbox.push({ v: 1, ...obj });
  }

  function siarkan(room, obj, kecuali) {
    for (const k of rooms.get(room) ?? []) {
      if (k.user !== kecuali) balas(k, obj);
    }
  }

  function presence(room) {
    const anggota = rooms.get(room) ?? new Set();
    const members = [...new Set([...anggota].map((k) => k.user))].sort();
    siarkan(room, { type: "presence", room, members });
  }

  function halaman(room, cocok) {
    const calon = pesan.filter((p) => p.room === room && cocok(p));
    return { messages: calon.slice(-BATAS), more: calon.length > BATAS };
  }

  function keluar(k, room) {
    if (!k.rooms.delete(room)) return;
    rooms.get(room).delete(k);
    presence(room);
  }

  function kirimPesan(k, e) {
    const cid = e.cid;
    const gagal = (code) => balas(k, { type: "error", code, cid, room: e.room });
    if (typeof cid !== "string" || cid.length < 1 || cid.length > 64) return gagal("bad_cid");
    const text = typeof e.text === "string" ? e.text.trim() : "";
    if (text.length < 1 || text.length > 1000) return gagal("bad_text");
    if (!k.rooms.has(e.room)) return gagal("not_member");
    const kunci = e.room + "|" + k.user + "|" + cid;
    const lama = sudahAda.get(kunci);
    if (lama) return balas(k, { type: "ack", room: e.room, cid, id: lama.id });
    const p = { id: ++idTerakhir, room: e.room, user: k.user, cid, text, ts: jam.t };
    pesan.push(p);
    sudahAda.set(kunci, p);
    balas(k, { type: "ack", room: e.room, cid, id: p.id });
    siarkan(e.room, { type: "message", ...p });
  }

  function terima(k, teks) {
    let e;
    try {
      e = JSON.parse(teks);
    } catch {
      return balas(k, { type: "error", code: "bad_json" });
    }
    if (!e || typeof e !== "object" || Array.isArray(e)) return balas(k, { type: "error", code: "bad_json" });
    if (e.v !== 1) return balas(k, { type: "error", code: "bad_version" });
    const room = e.room;
    if (["join", "leave", "send", "history", "typing"].includes(e.type) && !(typeof room === "string" && ROOM.test(room))) {
      return balas(k, { type: "error", code: "bad_room", cid: e.cid });
    }
    switch (e.type) {
      case "join": {
        if (!rooms.has(room)) rooms.set(room, new Set());
        rooms.get(room).add(k);
        k.rooms.add(room);
        const after = Number.isInteger(e.after) ? e.after : 0;
        balas(k, { type: "joined", room, ...halaman(room, (p) => p.id > after) });
        return presence(room);
      }
      case "leave":
        return keluar(k, room);
      case "send":
        return kirimPesan(k, e);
      case "history": {
        if (!k.rooms.has(room)) return balas(k, { type: "error", code: "not_member", room });
        const before = Number.isInteger(e.before) ? e.before : Infinity;
        return balas(k, { type: "history", room, ...halaman(room, (p) => p.id < before) });
      }
      case "typing":
        if (!k.rooms.has(room)) return balas(k, { type: "error", code: "not_member", room });
        return siarkan(room, { type: "typing", room, user: k.user }, k.user);
      default:
        return balas(k, { type: "error", code: "bad_type" });
    }
  }

  return {
    sambung(user) {
      const k = { user, rooms: new Set(), inbox: [], aktif: true };
      k.kirim = (teks) => {
        if (k.aktif) terima(k, teks);
      };
      k.putus = () => {
        if (!k.aktif) return;
        k.aktif = false;
        for (const room of [...k.rooms]) keluar(k, room);
      };
      balas(k, { type: "hello", user });
      return k;
    },
  };
}

