function pilihTeknik(kebutuhan) {
  const { duaArah, perMenit, bisaStreaming } = kebutuhan;
  if (!bisaStreaming) return "polling";
  if (duaArah) return "websocket";
  if (perMenit < 1) return "polling";
  return "sse";
}

function bebanPolling(klien, intervalDetik, menit) {
  const perKlien = Math.floor((menit * 60) / intervalDetik);
  return klien * perKlien;
}

