solution.code:
function bacaHeader(teks) {
  const baris = teks.split("\r\n");
  const header = {};
  for (const b of baris.slice(1)) {
    const i = b.indexOf(":");
    if (i > 0) header[b.slice(0, i).trim().toLowerCase()] = b.slice(i + 1).trim();
  }
  return { pertama: baris[0], header };
}

function cekHandshake(teks) {
  const { pertama, header } = bacaHeader(teks);
  if (!pertama.startsWith("GET ")) return { status: 400 };
  const upgrade = (header["upgrade"] ?? "").toLowerCase();
  const connection = (header["connection"] ?? "").toLowerCase();
  if (upgrade !== "websocket") return { status: 400 };
  if (!connection.split(",").some((x) => x.trim() === "upgrade")) return { status: 400 };
  if (!header["sec-websocket-key"]) return { status: 400 };
  const versi = header["sec-websocket-version"];
  if (!versi) return { status: 400 };
  if (versi !== "13") return { status: 426 };
  return { status: 101 };
}

const OPCODE = { 0x0: "lanjutan", 0x1: "teks", 0x2: "biner", 0x8: "close", 0x9: "ping", 0xa: "pong" };

function artiOpcode(n) {
  return OPCODE[n] ?? "tidak dikenal";
}

