solution.code:
const ROOM = /^[a-z0-9-]{1,32}$/;
const CID = /^[A-Za-z0-9-]{8,64}$/;
const isId = (n) => Number.isSafeInteger(n) && n >= 0;

function parseClientEvent(teks) {
  let ev;
  try {
    ev = JSON.parse(teks);
  } catch {
    return { error: "bad_json" };
  }
  if (ev === null || typeof ev !== "object") return { error: "bad_json" };
  if (ev.v !== 1) return { error: "bad_version" };
  if (typeof ev.room !== "string" || !ROOM.test(ev.room)) return { error: "bad_room" };
  const { type, room } = ev;
  switch (type) {
    case "leave":
    case "typing":
      return { type, room };
    case "join":
      if (ev.after !== undefined && !isId(ev.after)) return { error: "bad_cursor" };
      return { type, room, after: ev.after };
    case "history":
      if (!isId(ev.before)) return { error: "bad_cursor" };
      return { type, room, before: ev.before };
    case "send": {
      if (typeof ev.cid !== "string" || !CID.test(ev.cid)) return { error: "bad_cid" };
      const text = typeof ev.text === "string" ? ev.text.trim() : "";
      if (!text || text.length > 1000) return { error: "bad_text", cid: ev.cid };
      return { type, room, cid: ev.cid, text };
    }
    default:
      return { error: "bad_type" };
  }
}

