solution.code:
function buatHub() {
  const rooms = new Map(); // room -> Set<ws>

  function join(room, ws) {
    if (!rooms.has(room)) rooms.set(room, new Set());
    rooms.get(room).add(ws);
  }

  function leave(room, ws) {
    const set = rooms.get(room);
    if (!set) return;
    set.delete(ws);
    if (set.size === 0) rooms.delete(room);
  }

  function siarkan(room, event, kecuali) {
    const teks = JSON.stringify(event);
    let n = 0;
    for (const ws of rooms.get(room) ?? []) {
      if (ws === kecuali || ws.readyState !== WebSocket.OPEN) continue;
      ws.send(teks);
      n++;
    }
    return n;
  }

  function anggota(room) {
    const nama = [...(rooms.get(room) ?? [])].map((ws) => ws.user);
    return [...new Set(nama)].sort();
  }

  return { join, leave, siarkan, anggota };
}

