solution.code:
function simpanPesan(store, room, user, cid, text) {
  const kunci = room + "|" + user + "|" + cid;
  const lama = store.kunci.get(kunci);
  if (lama) return { pesan: lama, baru: false };
  const pesan = { id: ++store.idTerakhir, room, user, cid, text, ts: jam.t };
  store.pesan.push(pesan);
  store.kunci.set(kunci, pesan);
  return { pesan, baru: true };
}

function ambilRiwayat(pesan, before, limit = 50) {
  const calon = before == null ? pesan : pesan.filter((p) => p.id < before);
  return {
    messages: calon.slice(Math.max(0, calon.length - limit)),
    more: calon.length > limit,
  };
}

function gabungPesan(lama, baru) {
  const perId = new Map();
  for (const p of [...lama, ...baru]) {
    if (!perId.has(p.id)) perId.set(p.id, p);
  }
  return [...perId.values()].sort((a, b) => a.id - b.id);
}

