solution.code:
function buatInstance(wss, bus) {
  const rooms = new Map(); // nama room -> Set socket lokal

  function siarkanLokal(room, teks) {
    for (const ws of rooms.get(room) ?? []) {
      if (ws.readyState === WebSocket.OPEN) ws.send(teks);
    }
  }

  bus.subscribe("chat", (teks) => {
    const ev = JSON.parse(teks);
    siarkanLokal(ev.room, teks);
  });

  wss.on("connection", (ws) => {
    ws.on("message", (data) => {
      const ev = JSON.parse(data.toString());
      if (ev.type === "join") {
        if (!rooms.has(ev.room)) rooms.set(ev.room, new Set());
        rooms.get(ev.room).add(ws);
      } else if (ev.type === "send") {
        const pesan = { type: "message", room: ev.room, user: ws.user, text: ev.text };
        bus.publish("chat", JSON.stringify(pesan));
      }
    });
    ws.on("close", () => {
      for (const anggota of rooms.values()) anggota.delete(ws);
    });
  });
}

