// mini-ws: tiny stand-in for the server side of the "ws" package (no network in this sandbox).
// Same as the real one: wss.clients (Set), wss.on("connection", (ws, request) => ...),
// ws.on("message" | "close" | "error" | "pong", fn), ws.send(), ws.readyState, ws.ping(),
// ws.terminate(), ws.close(code, reason), WebSocket.OPEN. Message data has toString() like a Buffer.
// Stricter than ws: send() on a socket that is not OPEN throws, so mistakes are visible.
// Test controls start with "_": wss._sambung(info), ws._pesan(text), ws._pong(), ws._putus(), ws._punya(event).
const WebSocket = { CONNECTING: 0, OPEN: 1, CLOSING: 2, CLOSED: 3 };
function buatWss() {
  const onConn = [];
  const wss = {
    clients: new Set(),
    on(ev, fn) { if (ev === "connection") onConn.push(fn); },
    _sambung(info = {}) {
      const h = {};
      const emit = (ev, ...a) => (h[ev] ?? []).forEach((fn) => fn(...a));
      const selesai = (code, reason) => {
        if (ws.readyState === 3) return;
        ws.readyState = 3; wss.clients.delete(ws); emit("close", code, reason);
      };
      const ws = {
        readyState: 1, terkirim: [], jumlahPing: 0, user: info.user,
        on(ev, fn) { (h[ev] ??= []).push(fn); },
        send(d) { if (ws.readyState !== 1) throw new Error("WebSocket is not open"); ws.terkirim.push(String(d)); },
        ping() { ws.jumlahPing++; },
        terminate() { selesai(1006, ""); },
        close(code = 1000, reason = "") { selesai(code, reason); },
        _pesan(teks) { emit("message", { toString: () => teks }, false); },
        _pong() { emit("pong"); },
        _putus() { selesai(1006, ""); },
        _punya(ev) { return (h[ev] ?? []).length > 0; },
      };
      wss.clients.add(ws);
      onConn.forEach((fn) => fn(ws, { url: info.url ?? "/", headers: info.headers ?? {} }));
      return ws;
    },
  };
  return wss;
}

// mini-bus: in-memory pub/sub like Redis PUBLISH/SUBSCRIBE (synchronous, string messages, nothing stored).
function buatBus() {
  const subs = new Map();
  return {
    publish(channel, pesan) {
      if (typeof pesan !== "string") throw new Error("pesan harus string");
      const fns = subs.get(channel) ?? [];
      fns.forEach((fn) => fn(pesan, channel));
      return fns.length; // like Redis: number of subscribers that got it
    },
    subscribe(channel, fn) {
      if (!subs.has(channel)) subs.set(channel, []);
      subs.get(channel).push(fn);
    },
  };
}

function siapkan() {
  const bus = buatBus();
  const A = buatWss();
  const B = buatWss();
  buatInstance(A, bus);
  buatInstance(B, bus);
  return { bus, A, B };
}

function masuk(wss, user, room) {
  const ws = wss._sambung({ user });
  ws._pesan(JSON.stringify({ type: "join", room }));
  return ws;
}

const kirim = (ws, room, text) => ws._pesan(JSON.stringify({ type: "send", room, text }));
const pesanMasuk = (ws) => ws.terkirim.map((t) => JSON.parse(t)).filter((e) => e.type === "message");

chapters.body:
## Tujuan

- Membuat endpoint Server-Sent Events dengan Express dan memakainya lewat `EventSource` di browser.
- Menulis event SSE dengan `id`, `event`, `data`, `retry`, komentar keep-alive, dan menyusul dengan `Last-Event-ID`.
- Menyiapkan proxy Nginx untuk WebSocket dan memahami kapan sticky session diperlukan.
- Mematikan server dengan rapi saat deploy dan mengenali platform yang tidak cocok untuk WebSocket.

## Tidak semua hal butuh WebSocket

Sepanjang kelas ini kamu membangun chat, yang memang butuh komunikasi dua arah yang cepat. Tapi banyak fitur "realtime" di aplikasi sekolah sebenarnya satu arah saja. Notifikasi "nilai ulangan MTK sudah keluar", papan skor lomba 17 Agustus, atau status antrean kantin: server mendorong data, browser cukup menampilkan. Kalau siswa perlu melakukan sesuatu, misalnya menandai notifikasi sudah dibaca, request HTTP biasa sudah cukup.

Untuk kebutuhan seperti ini ada **Server-Sent Events (SSE)**. SSE berjalan di atas HTTP biasa: browser membuat satu request, server membalas dengan respons yang tidak pernah ditutup, lalu terus menulis event ke dalamnya. Tidak ada upgrade, tidak ada frame, tidak ada paket tambahan di server.

## Endpoint SSE dengan Express

Respons SSE memakai `Content-Type: text/event-stream`. Setiap event terdiri dari beberapa baris `nama: nilai`, lalu diakhiri **satu baris kosong**:

```js
app.get("/notif", (req, res) => {
  res.set({
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
  });
  res.flushHeaders();

  res.write("retry: 5000\n\n");
  const kirim = (id, event, data) => {
    res.write(`id: ${id}\nevent: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  };
  pendengar.add(kirim);

  const detak = setInterval(() => res.write(": ping\n\n"), 25000);
  req.on("close", () => {
    clearInterval(detak);
    pendengar.delete(kirim);
  });
});
```

Arti setiap bagian:

- `data:` berisi isi event. SSE hanya mengirim teks, jadi objek diubah ke JSON dulu. Kalau isinya lebih dari satu baris, setiap baris ditulis sebagai baris `data:` sendiri, dan browser menggabungkannya lagi dengan karakter baris baru.
- `event:` memberi nama event. Tanpa baris ini, event bernama `message`.
- `id:` menandai event. Browser mengingat id terakhir yang diterima.
- `retry:` memberi tahu browser berapa milidetik menunggu sebelum menyambung lagi kalau koneksi putus.
- Baris yang diawali titik dua, seperti `: ping`, adalah **komentar**. Browser mengabaikannya, tapi data tetap lewat, sehingga proxy tidak menganggap koneksi diam. Fungsinya mirip ping di WebSocket.

`res.flushHeaders()` mengirim header segera, supaya browser tahu stream sudah dimulai walaupun event pertama belum ada. Listener `req.on("close")` penting untuk membersihkan timer dan daftar pendengar saat browser menutup tab.

![Endpoint SSE di Express dan EventSource di browser](slide:29)

## EventSource di browser

Di sisi browser, kodenya pendek:

```js
const sumber = new EventSource("/notif");

sumber.addEventListener("nilai", (e) => {
  const n = JSON.parse(e.data);
  tampilkan(`Nilai ${n.mapel} sudah keluar: ${n.nilai}`);
});

sumber.onerror = () => tampilkanStatus("menyambung ulang...");
```

Inilah keunggulan terbesar SSE: **browser menyambung ulang sendiri**. Kamu tidak perlu menulis backoff seperti di bab heartbeat. Lebih bagus lagi, saat menyambung ulang browser mengirim header `Last-Event-ID` berisi id event terakhir yang diterima. Server tinggal membaca header itu dan mengirim event yang terlewat:

```js
const terakhir = Number(req.get("Last-Event-ID"));
if (!Number.isNaN(terakhir)) {
  for (const ev of log.filter((e) => e.id > terakhir)) kirim(ev.id, ev.event, ev.data);
}
```

Ini konsep yang sama dengan `join` berisi `after` di chat, hanya saja browser sudah mengurus sisi kliennya.

Kapan SSE cukup? Saat data mengalir satu arah dari server, berupa teks, dan tidak terlalu sering dari sisi klien. Kapan perlu WebSocket? Saat klien juga mengirim banyak event cepat (chat, game, kursor bersama) atau butuh data biner. Satu catatan: di HTTP/1.1, browser membatasi sekitar 6 koneksi ke satu domain. Kalau siswa membuka 7 tab yang masing-masing memakai SSE, tab ketujuh bisa macet. HTTP/2 tidak punya masalah ini karena banyak stream berbagi satu koneksi.

## Deploy di belakang proxy

Sekarang saatnya memasang server chat di VPS sekolah, biasanya di belakang Nginx yang juga mengurus TLS. Konfigurasi WebSocket butuh perhatian khusus, karena header `Upgrade` dan `Connection` termasuk header *hop-by-hop* yang secara bawaan tidak diteruskan proxy:

```nginx
location /ws {
  proxy_pass http://chat;
  proxy_http_version 1.1;
  proxy_set_header Upgrade $http_upgrade;
  proxy_set_header Connection "upgrade";
  proxy_read_timeout 120s;
}
```

- `proxy_http_version 1.1` wajib, karena mekanisme upgrade tidak ada di HTTP/1.0.
- Dua baris `proxy_set_header` meneruskan permintaan upgrade dari browser ke server Node.js.
- `proxy_read_timeout` (bawaan 60 detik) harus lebih lama dari interval ping. Kalau server mem-ping tiap 30 detik, 120 detik memberi ruang aman.

Dengan TLS di Nginx, browser tersambung ke `wss://`, sedangkan Nginx ke Node.js boleh memakai `ws://` biasa di jaringan internal. Halaman yang dibuka lewat `https://` memang harus memakai `wss://`, karena browser memblokir koneksi `ws://` dari halaman aman.

Untuk endpoint SSE, matikan juga buffering di proxy (di Nginx `proxy_buffering off`, atau kirim header `X-Accel-Buffering: no` dari server), supaya event tidak tertahan di proxy.

## Sticky session, kapan perlu?

Kalau kamu menjalankan beberapa instance, load balancer membagi koneksi ke instance-instance itu. **Sticky session** berarti request dari klien yang sama selalu diarahkan ke instance yang sama.

Untuk WebSocket murni, satu koneksi memang tetap di satu instance selama hidupnya, jadi sticky session tidak diperlukan. Pesan lintas instance diurus Redis seperti di bab sebelumnya. Lain halnya dengan Socket.IO yang memakai transport long-polling: satu sesi terdiri dari banyak request HTTP terpisah, dan semuanya harus sampai ke instance yang sama. Di situ sticky session wajib.

## Mematikan server dengan rapi

Setiap kali deploy versi baru, server lama dimatikan. Process manager atau platform container biasanya mengirim sinyal `SIGTERM` lebih dulu. Manfaatkan sinyal itu:

```js
process.on("SIGTERM", () => {
  server.close();
  for (const ws of wss.clients) ws.close(1001, "server restart");
});
```

Kode **1001** berarti "pergi" (*going away*). Klien menerima `onclose` dengan kode itu, lalu menyambung lagi dengan backoff dan jitter dari bab heartbeat. Pesan yang belum di-ack dikirim ulang, dan berkat server idempotent tidak ada yang ganda. Semua bagian yang kamu pelajari ternyata saling menopang.

Terakhir, hindari platform **serverless** berbasis fungsi yang berumur pendek untuk server WebSocket. Fungsi seperti itu dirancang untuk menjawab satu request lalu selesai, sedangkan WebSocket butuh proses yang hidup selama koneksi terbuka. Pilih VPS, container, atau layanan yang memang mendukung koneksi panjang.

## Langkah berikutnya

Kamu sudah punya semua kepingnya: handshake, protokol bertipe, room, heartbeat, reconnect, ack, dedupe, cursor, autentikasi, rate limit, dan Redis. Gabungkan semuanya di **Studio Proyek Aplikasi Chat Realtime**, dari `PROTOCOL.md` sampai dua instance yang berjalan bersama. Sebelum itu, kerjakan proyek akhir kelas ini, Server Chat Mini, untuk memastikan logika protokolnya sudah kamu kuasai tanpa gangguan jaringan. Kalau proyeknya lolos, kamu tinggal memindahkan logika yang sama ke server `ws` sungguhan, menambahkan database, lalu menyalakan instance kedua.

## Rangkuman

- SSE memakai HTTP biasa dengan `text/event-stream`; event berisi baris `id`, `event`, `data`, `retry`, diakhiri baris kosong, dan komentar `:` untuk keep-alive.
- `EventSource` menyambung ulang otomatis dan mengirim `Last-Event-ID`, jadi server bisa menyusulkan event.
- Nginx butuh `proxy_http_version 1.1`, header `Upgrade` dan `Connection`, serta `proxy_read_timeout` di atas interval ping.
- Sticky session wajib untuk long-polling Socket.IO, tidak untuk WebSocket murni.
- Saat `SIGTERM`, tutup klien dengan kode 1001; hindari serverless berumur pendek untuk WebSocket.

