solution.code:
function formatSse({ id, event, data, retry }) {
  const baris = [];
  if (id !== undefined) baris.push("id: " + id);
  if (event !== undefined) baris.push("event: " + event);
  if (retry !== undefined) baris.push("retry: " + retry);
  const teks = typeof data === "string" ? data : JSON.stringify(data);
  for (const isi of teks.split("\n")) baris.push("data: " + isi);
  return baris.join("\n") + "\n\n";
}

function susulanSse(log, lastEventId) {
  if (lastEventId === undefined || lastEventId === null) return [];
  const terakhir = Number(lastEventId);
  if (lastEventId === "" || Number.isNaN(terakhir)) return log.slice();
  return log.filter((e) => e.id > terakhir);
}
